"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacyDiffTable from "../beautiful-ui/primitives/DiffTable";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type DiffTableProps = NonNullable<ComponentProps<typeof LegacyDiffTable>>;

export const DiffTable = forwardRef<HTMLDivElement, DiffTableProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacyDiffTable {...props} />
  </BeautifulUIRoot>
));

DiffTable.displayName = "DiffTable";

export default DiffTable;

"use client";

import { useEffect, useState, type CSSProperties } from "react";
import { Button } from "@/components/ui/button";
import { useShape } from "@/lib/shape-context";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "../hooks/useReducedMotion";
import "../beautiful-ui.css";

/* ─────────────────────────────────────────────────────────
 * DIFF TABLE
 * The proposed edit plays once and rests on the completed
 * diff. Each changed row is the control: click it to include
 * or exclude that specific addition/removal before applying.
 * ───────────────────────────────────────────────────────── */

function useStage(steps: number[], reducedMotion: boolean) {
  const [stage, setStage] = useState(0);
  useEffect(() => {
    if (reducedMotion) {
      setStage(steps.length);
      return;
    }
    if (stage >= steps.length) return;
    const t = setTimeout(() => setStage((s) => s + 1), steps[stage]);
    return () => clearTimeout(t);
  }, [reducedMotion, stage, steps]);
  return stage;
}

const STAGE_DELAYS = [180, 260];

const ROWS = [
  { key: "rocky", id: "Rocky Road", dept: "Classic", email: "aurora-scoops", removed: true },
  { key: "bubblegum", id: "Bubblegum", dept: "Retro", email: "kumo-creamery", removed: true },
  { key: "mint", id: "Mint Chip", dept: "Classic", email: "maple-orbit", removed: false },
];

const DOT: Record<string, string> = {
  Classic: "bg-[var(--bui-focus)]",
  Retro: "bg-[var(--ink-3)]",
  Seasonal: "bg-[var(--orange)]",
};

function IncludedMark({ included, tone }: { included: boolean; tone: "red" | "green" }) {
  return (
    <span
      aria-hidden
      className={`flex size-4.5 shrink-0 items-center justify-center rounded-[5px] transition-[background-color,color,transform] duration-160 ${
        included
          ? tone === "red"
            ? "bg-[var(--diff-removal-ink)] text-background"
            : "bg-[var(--diff-addition-ink)] text-background"
          : "bg-hover text-muted-foreground ring-1 ring-border/60"
      }`}
      style={{ transform: included ? "scale(1)" : "scale(0.92)" }}
    >
      {included ? (
        <svg
          width="11"
          height="11"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="3"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M20 6L9 17l-5-5" />
        </svg>
      ) : null}
    </span>
  );
}

export interface DiffTableProps {
  onApply?: (edits: { removals: number; additions: number }) => void;
}

export default function DiffTable({ onApply }: DiffTableProps = {}) {
  const shape = useShape();
  const reducedMotion = useReducedMotion();
  const stage = useStage(STAGE_DELAYS, reducedMotion);
  // 0 plain · 1 removals · 2 completed diff
  const tinted = stage >= 1;
  const settled = stage >= 2;
  const [accepted, setAccepted] = useState(false);
  const [edits, setEdits] = useState<Record<string, boolean>>({
    rocky: true,
    bubblegum: true,
    pistachio: true,
  });

  const removals = ["rocky", "bubblegum"].filter((key) => edits[key]).length;
  const additions = edits.pistachio ? 1 : 0;
  const showAdded = settled;

  const toggleEdit = (key: string) => setEdits((current) => ({ ...current, [key]: !current[key] }));

  return (
    <div className="w-full max-w-95">
      <div
        className={cn(
          "relative overflow-hidden bg-[var(--surface)] shadow-surface-2",
          shape.container,
        )}
        style={
          {
            "--diff-removal-surface": "color-mix(in oklab, var(--destructive) 8%, var(--surface))",
            "--diff-addition-surface":
              "color-mix(in oklab, var(--success,#22c55e) 8%, var(--surface))",
            "--diff-removal-ink": "color-mix(in oklab, var(--destructive) 72%, var(--foreground))",
            "--diff-addition-ink":
              "color-mix(in oklab, var(--success,#22c55e) 65%, var(--foreground))",
          } as CSSProperties
        }
      >
        <div className="primitive-card-bar flex items-center justify-between border-b border-border/40">
          <span className="text-[13px] font-medium text-foreground">Proposed menu cleanup</span>
          {settled && !accepted && (
            <span className="text-[11px] text-muted-foreground">Click changed rows to toggle</span>
          )}
        </div>

        <table className="w-full table-fixed border-collapse text-left">
          <caption className="sr-only">
            Proposed menu changes. Use each changed row control to include or exclude the edit.
          </caption>
          <colgroup>
            <col className="w-[34%]" />
            <col className="w-[30%]" />
            <col className="w-[36%]" />
          </colgroup>
          <thead>
            <tr className="border-b border-border/40">
              {["Flavor", "Category", "Supplier"].map((h) => (
                <th
                  key={h}
                  className="primitive-table-cell text-[12px] font-medium text-muted-foreground"
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {ROWS.map((row) => {
              const out = row.removed && tinted && edits[row.key];
              return (
                <tr
                  key={row.key}
                  className="border-b border-border/40 transition-[background-color,filter,opacity] duration-80 last:border-0"
                  style={{ background: out ? "var(--diff-removal-surface)" : undefined }}
                >
                  <td
                    className="primitive-table-cell text-[13px] font-medium tabular-nums transition-colors duration-160"
                    style={{ color: out ? "var(--diff-removal-ink)" : "var(--foreground)" }}
                  >
                    {row.id}
                  </td>
                  <td className="primitive-table-cell">
                    <span
                      className={cn(
                        "inline-flex h-5.5 items-center gap-1.5 bg-hover px-2 text-[12px] font-medium",
                        shape.item,
                      )}
                    >
                      <span className={`size-1.5 rounded-full ${DOT[row.dept]}`} />
                      <span className="text-muted-foreground">{row.dept}</span>
                    </span>
                  </td>
                  <td
                    className="primitive-table-cell text-[13px] whitespace-nowrap transition-colors duration-160"
                    style={{
                      color: out ? "var(--diff-removal-ink)" : "var(--muted-foreground)",
                      textDecorationLine: out ? "line-through" : "none",
                      textDecorationColor:
                        "color-mix(in oklab, var(--diff-removal-ink) 50%, transparent)",
                    }}
                  >
                    <span className="flex items-center justify-between gap-2">
                      <span className="min-w-0 truncate">{row.email}</span>
                      {row.removed && settled && (
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon-sm"
                          aria-label={`${edits[row.key] ? "Exclude" : "Include"} removing ${row.id}`}
                          aria-pressed={edits[row.key]}
                          disabled={accepted}
                          onClick={() => toggleEdit(row.key)}
                          className="size-8 shrink-0 p-0 focus-visible:!outline-none [&_svg]:h-3 [&_svg]:w-3"
                        >
                          <IncludedMark included={edits[row.key]} tone="red" />
                        </Button>
                      )}
                    </span>
                  </td>
                </tr>
              );
            })}
            {/* added row */}
            <tr>
              <td colSpan={3} className="p-0">
                <div
                  className="grid transition-[grid-template-rows,opacity] duration-160"
                  style={{
                    gridTemplateRows: showAdded ? "1fr" : "0fr",
                    opacity: showAdded ? 1 : 0,
                    transitionTimingFunction: "cubic-bezier(0.23, 1, 0.32, 1)",
                  }}
                >
                  <div className="overflow-hidden">
                    <div
                      className="grid grid-cols-[34%_30%_36%] items-center border-t border-border/40 transition-[background-color,filter,opacity] duration-80"
                      style={{
                        background: edits.pistachio ? "var(--diff-addition-surface)" : undefined,
                      }}
                    >
                      <span
                        className="primitive-table-cell text-[13px] font-medium tabular-nums transition-colors duration-160"
                        style={{
                          color: edits.pistachio ? "var(--diff-addition-ink)" : "var(--foreground)",
                        }}
                      >
                        Pistachio
                      </span>
                      <span className="primitive-table-cell">
                        <span
                          className={cn(
                            "inline-flex h-5.5 items-center gap-1.5 bg-hover px-2 text-[12px] font-medium",
                            shape.item,
                          )}
                        >
                          <span className="size-1.5 rounded-full bg-[var(--diff-addition-ink)]" />
                          <span className="text-muted-foreground">Seasonal</span>
                        </span>
                      </span>
                      <span
                        className="primitive-table-cell text-[13px] transition-colors duration-160"
                        style={{
                          color: edits.pistachio
                            ? "var(--diff-addition-ink)"
                            : "var(--muted-foreground)",
                        }}
                      >
                        <span className="flex items-center justify-between gap-2">
                          <span className="min-w-0 truncate">maple-orbit</span>
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon-sm"
                            aria-label={`${edits.pistachio ? "Exclude" : "Include"} adding Pistachio`}
                            aria-pressed={edits.pistachio}
                            disabled={accepted}
                            onClick={() => toggleEdit("pistachio")}
                            className="size-8 shrink-0 p-0 focus-visible:!outline-none [&_svg]:h-3 [&_svg]:w-3"
                          >
                            <IncludedMark included={edits.pistachio} tone="green" />
                          </Button>
                        </span>
                      </span>
                    </div>
                  </div>
                </div>
              </td>
            </tr>
          </tbody>
        </table>

        {/* footer — the summary follows the row-level selection */}
        {settled && (
          <div
            className="primitive-card-footer flex min-h-11 items-center justify-between border-t border-border/40"
            style={{ animation: "fade-up 160ms cubic-bezier(0.23,1,0.32,1) both" }}
          >
            {accepted ? (
              <span
                role="status"
                className={cn(
                  "inline-flex items-center gap-1.5 bg-[var(--diff-addition-surface)] py-1 pr-2.5 pl-1 text-[13px] font-medium text-[color:var(--diff-addition-ink)]",
                  shape.item,
                )}
                style={{ animation: "pop-in 160ms cubic-bezier(0.23,1,0.32,1) both" }}
              >
                <span className="flex size-4.5 items-center justify-center rounded-full bg-[var(--diff-addition-ink)] text-background">
                  <svg
                    width="11"
                    height="11"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="3"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <path d="M20 6L9 17l-5-5" />
                  </svg>
                </span>
                {removals + additions} {removals + additions === 1 ? "edit" : "edits"} applied
              </span>
            ) : (
              <>
                <span className="text-[12px] tabular-nums text-muted-foreground">
                  {removals} {removals === 1 ? "removal" : "removals"} · {additions}{" "}
                  {additions === 1 ? "addition" : "additions"}
                </span>
                <span className="flex items-center gap-1.5">
                  <Button
                    type="button"
                    variant="primary"
                    size="sm"
                    disabled={removals + additions === 0}
                    onClick={() => {
                      setAccepted(true);
                      onApply?.({ removals, additions });
                    }}
                    className="text-[12px] focus-visible:!outline-none"
                  >
                    Apply {removals + additions} {removals + additions === 1 ? "change" : "changes"}
                  </Button>
                </span>
              </>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import "./beautiful-ui.css";
import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { SurfaceProvider, useSurface } from "@/lib/surface-context";
import { useShapeVariant } from "@/lib/shape-context";

export type BeautifulUIRootProps = HTMLAttributes<HTMLDivElement>;

type AdapterStyle = CSSProperties & Record<`--${string}`, string | number>;

function clampSurface(level: number) {
  return Math.max(1, Math.min(8, level));
}

function createAdapterStyle(
  substrate: number,
  surface: number,
  style?: CSSProperties,
): AdapterStyle {
  const inset = clampSurface(substrate + 1);
  const overlay = clampSurface(surface + 2);
  const raisedOverlay = clampSurface(surface + 4);

  return {
    "--page": `var(--surface-${substrate})`,
    "--canvas": `var(--surface-${substrate})`,
    "--surface": `var(--surface-${surface})`,
    "--inset": `var(--surface-${inset})`,
    "--tooltip-bg": `var(--surface-${overlay})`,
    "--overlay-surface": `var(--surface-${overlay})`,
    "--overlay-raised": `var(--surface-${raisedOverlay})`,
    ...style,
  };
}

function useBeautifulUIScope(offset = 2) {
  const substrate = useSurface();
  const surface = clampSurface(substrate + offset);
  const shape = useShapeVariant();

  return {
    shape,
    substrate,
    surface,
    style: createAdapterStyle(substrate, surface),
  };
}

/**
 * Internal compatibility boundary for the adapted primitives. It has no layout
 * box of its own: public components use it internally so consumers inherit the
 * active BoringUI theme, surface level, and radius mode without a wrapper.
 */
export const BeautifulUIRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", "contents", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIRoot.displayName = "BeautifulUIRoot";

/** Applies the same BoringUI scope to content rendered in a body portal. */
export const BeautifulUIPortalRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIPortalRoot.displayName = "BeautifulUIPortalRoot";

export default BeautifulUIRoot;

